import pytest
import torch

from solver import solve


def load_case():
    try:
        return torch.load("data/case.pt")
    except FileNotFoundError:
        pytest.skip("reference data unavailable")


@pytest.mark.skip(reason="slow on CPU")
def test_large():
    assert solve(load_case(), mode="clean_only") is not None


def test_small():
    u = solve(load_case(), mode="clean_only")
    assert torch.allclose(u, u.T, atol=1e-6)
